def insert(root, key):  # 일반 BST 삽입 (균형 조정 없음)
    if root is None:
        return Node(key)
    if key < root.key:
        root.left = insert(root.left, key)
    else:
        root.right = insert(root.right, key)
    return root

def height(root):
    if root is None:
        return 0
    return 1 + max(height(root.left), height(root.right))

root = None
for k in [1, 2, 3, 4, 5]:  # 정렬된 입력
    root = insert(root, k)  # 매번 오른쪽 끝까지 내려감
print(height(root))  # 5 = n → 우편향 트리
